<?php
require_once __DIR__ . '/../../includes/admin_auth.php'; require_admin();
$search = trim((string) ($_GET['q'] ?? ''));
$statement = $pdo->prepare('SELECT id, title, slug, icon, image, status, updated_at FROM services WHERE CONCAT_WS(" ", title, slug, description) LIKE :search ORDER BY id DESC');
$statement->execute(['search' => '%' . $search . '%']); $services = $statement->fetchAll(); admin_header('Services', 'services/index.php');
?><div class="d-flex flex-wrap gap-2 justify-content-between mb-3"><form class="d-flex gap-2" method="get"><input class="form-control" name="q" value="<?= e($search) ?>" placeholder="Search services..."><button class="btn btn-outline-secondary" type="submit"><i class="bi bi-search"></i></button></form><a href="create.php" class="btn btn-primary"><i class="bi bi-plus-lg me-1"></i>Add Service</a></div><div class="card table-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Service</th><th>Icon</th><th>Status</th><th>Updated</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach ($services as $service): ?><tr><td><strong><?= e($service['title']) ?></strong><small class="d-block text-secondary"><?= e($service['slug']) ?></small></td><td><i class="bi <?= e($service['icon'] ?: 'bi-stars') ?> fs-5"></i></td><td><span class="badge text-bg-<?= $service['status'] ? 'success' : 'secondary' ?>"><?= $service['status'] ? 'Active' : 'Inactive' ?></span></td><td class="small text-secondary"><?= e(date('d M Y', strtotime($service['updated_at']))) ?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="edit.php?id=<?= e($service['id']) ?>">Edit</a> <a class="btn btn-sm btn-outline-danger" href="delete.php?id=<?= e($service['id']) ?>">Delete</a></td></tr><?php endforeach; ?><?php if (!$services): ?><tr><td colspan="5" class="text-center text-secondary py-5">No services found.</td></tr><?php endif; ?></tbody></table></div></div><?php admin_footer(); ?>